import pandas as pd

# Initialize a dictionary to store the first few rows of each DataFrame
data_preview = {}

# List of telemetry files and their corresponding names
files_to_preview = {
    'metric_node': '/telemetry/row/metric/metric_node.parquet',
    'metric_container': '/telemetry/row/metric/metric_container.parquet',
    'metric_service': '/telemetry/row/metric/metric_service.parquet',
    'metric_middleware': '/telemetry/row/metric/metric_middleware.parquet',
    'metric_app': '/telemetry/row/metric/metric_app.parquet',
    'trace_span': '/telemetry/row/trace/trace_span.parquet'
}

# Attempt to load each DataFrame and store the first few rows
for name, file in files_to_preview.items():
    try:
        df = pd.read_parquet(file)
        data_preview[name] = df.head().to_dict(orient='records')
    except Exception as e:
        data_preview[name] = str(e)

# The data_preview dictionary now contains the first few rows of each DataFrame.
